  ['notch · the one low point']: 'iegriezums · vien. minimums',
  ['pivot']: 'tapa',
  ['heart cam · r 3.36 → rMin 1.08 (0.32 r)']: 'sirds izc. · r 3.36 → rMin 1.08 (0.32 r)',
  ['r(θ) = rMin + (r − rMin)(1 − cos θ)/2']: 'r(θ) = rMin + (r − rMin)(1 − cos θ)/2',
