  ['1 0 SHOWN ring parity clamp']: '1 0 REDZAMS paritātes spaile',
  ['1 1 SHOWN ring parity + sleeve']: '1 1 REDZAMS paritāte + uzmava',
  ['armed']: 'aktiv.',
